L=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def answer():
    s=[r for r in rows if r[2][1]==0]
    w=sum(r[1] for r in s)
    posterior={m:float(F(sum(r[1] for r in s if r[0]==m),w)) for m in 'ABCD'}
    def repair(sub):
        z=sum(r[1] for r in sub)
        return min((sum(F(r[1],z)*L[a]['ABCD'.index(r[0])] for r in sub),'ABCD'[a]) for a in range(4))
    losses={m:sum(F(r[1],w)*L[a]['ABCD'.index(r[0])] for r in s) for a,m in enumerate('ABCD')}
    policies={}
    for t,c in [('T',F(7)),('V',F(17,10)),('W',F(21,10))]:
        val=c; p={}
        for v in (0,1):
            sub=[r for r in s if r[2]['TUVW'.index(t)]==v]
            if sub:
                loss,act=repair(sub)
                val+=F(sum(r[1] for r in sub),w)*loss
                p[str(v)]=act
            else:p[str(v)]='IMPOSSIBLE'
        losses[t]=val; policies[t]=p
    act=min(losses,key=losses.get)
    return {'posterior':posterior,'remaining_losses':{k:float(v) for k,v in losses.items()},'action':act,'repair_after':policies.get(act,{})}
